fn worker() {
  let values = [0]
  let alias = values
  let count = 0
  let bump = fn() { set count = num.add(count, 1) return count }
  for step in [1, 2, 3] {
    do apply bump()
    set alias[0] = num.add(values[0], step)
    do sleep 5000
  }
  return (values[0], count, alias[0])
}
